// PurgeBeacons只删真实30天前有界明细，未完成派生的page-view另记真实漏数。
func PurgeBeacons(ctx context.Context,op OperationContext,in PurgeBeaconsInput)(PurgeBeaconsResult,error){
 now,err:=time.Parse(time.RFC3339Nano,in.Now);if err!=nil{return PurgeBeaconsResult{},platform.NewError(platform.CodeValidation,false,"保留期时间不合法")};limit:=in.BatchSize;if limit<1||limit>500{limit=500};work,rt,tx,cancel,err:=beginWrite(ctx,op);if err!=nil{return PurgeBeaconsResult{},err};defer cancel();defer tx.Rollback()
 var zone string;if err=tx.QueryRowContext(work,`SELECT reporting_timezone FROM analytics_meta WHERE singleton=1`).Scan(&zone);err!=nil{return PurgeBeaconsResult{},storageError(err)};var location *time.Location;if zone!=""{location,err=time.LoadLocation(zone);if err!=nil{return PurgeBeaconsResult{},platform.NewError(platform.CodeIntegrityError,false,"原匿名计数日界线损坏")}}
 rows,err:=tx.QueryContext(work,`SELECT beacon_id,event_type,occurred_at FROM beacon_inbox WHERE occurred_at<? AND data_epoch=? ORDER BY occurred_at,beacon_id LIMIT ?`,now.UTC().AddDate(0,0,-30).Format(analyticsTimeLayout),rt.Epoch,limit);if err!=nil{return PurgeBeaconsResult{},storageError(err)};type item struct{ID,Kind,At string};items:=[]item{};for rows.Next(){var row item;if err=rows.Scan(&row.ID,&row.Kind,&row.At);err!=nil{break};items=append(items,row)};if err==nil{err=rows.Err()};_ = rows.Close();if err!=nil{return PurgeBeaconsResult{},storageError(err)}
 var lost int64;for _,item:=range items{if item.Kind=="page-view"{if location==nil{return PurgeBeaconsResult{},platform.NewError(platform.CodeIntegrityError,false,"旧匿名明细无法证明计数时区")};at,e:=time.Parse(analyticsTimeLayout,item.At);if e!=nil{return PurgeBeaconsResult{},platform.NewError(platform.CodeIntegrityError,false,"匿名明细时间损坏")};for _,period:=range [][2]string{{"hourly",at.UTC().Truncate(time.Hour).Format(analyticsTimeLayout)},{"daily",at.In(location).Format("2006-01-02")+"/"+zone}}{var complete int;err=tx.QueryRowContext(work,`SELECT count(*) FROM aggregate_runs a JOIN beacon_period_watermarks p ON p.kind=a.kind AND p.period_key=a.period_key AND p.revision=a.source_watermark WHERE a.kind=? AND a.period_key=?`,period[0],period[1]).Scan(&complete);if err!=nil{return PurgeBeaconsResult{},storageError(err)};if complete==0{lost++;break}}};if _,err=tx.ExecContext(work,`DELETE FROM beacon_inbox WHERE beacon_id=?`,item.ID);err!=nil{return PurgeBeaconsResult{},storageError(err)}}
 if lost!=0{result,e:=tx.ExecContext(work,`UPDATE analytics_meta SET dropped=dropped+? WHERE singleton=1 AND dropped<=9223372036854775807-?`,lost,lost);if e!=nil{return PurgeBeaconsResult{},storageError(e)};count,e:=result.RowsAffected();if e!=nil{return PurgeBeaconsResult{},storageError(e)};if count!=1{return PurgeBeaconsResult{},platform.NewError(platform.CodeBudgetExceeded,false,"漏数超过精确整数预算")}}
 if len(items)!=0{if _,err=advanceWatermark(work,tx,"beacon-retention");err!=nil{return PurgeBeaconsResult{},err}};if err=tx.Commit();err!=nil{return PurgeBeaconsResult{},storageError(err)};return PurgeBeaconsResult{Deleted:int64(len(items))},nil
}

// PurgeAuditHistory只删可证明链的最老连续前缀，原锚与本次保留期审计同事务。
func PurgeAuditHistory(ctx context.Context,op OperationContext,in PurgeAuditHistoryInput)(PurgeAuditHistoryResult,error){
 rt,err:=runtimeFrom(ctx,op);if err!=nil{return PurgeAuditHistoryResult{},err};if !(op.CallerService=="analytics"&&op.Actor.Kind=="service"&&op.Actor.SubjectID=="analytics"){if rt.Authorize==nil{return PurgeAuditHistoryResult{},platform.NewError(platform.CodeDependencyUnavailable,true,"保留期当前权限未装配")};if err=rt.Authorize(ctx,op,"system.manage","analytics.retention");err!=nil{return PurgeAuditHistoryResult{},err}}
 days:=in.RetentionDays;if days==0{days=180};if days<30{return PurgeAuditHistoryResult{},platform.NewError(platform.CodeValidation,false,"审计保留期最少30天")};now,err:=time.Parse(time.RFC3339Nano,in.Now);if err!=nil{return PurgeAuditHistoryResult{},platform.NewError(platform.CodeValidation,false,"审计保留期时间不合法")};cutoff:="0000-01-01T00:00:00.000000000Z";if days<=3660000{cutoff=now.UTC().AddDate(0,0,-int(days)).Format(analyticsTimeLayout)}
 work,_,tx,cancel,err:=beginWrite(ctx,op);if err!=nil{return PurgeAuditHistoryResult{},err};defer cancel();defer tx.Rollback();input,_:=platform.CanonicalJSON(in);digest:=platform.HashBytes(input);result:=PurgeAuditHistoryResult{};found,err:=readReceipt(work,tx,op,"analytics.PurgeAuditHistory",digest,&result);if err!=nil{return result,err};if found{return result,nil}
 previous:=strings.Repeat("0",64);err=tx.QueryRowContext(work,`SELECT hash FROM audit_anchors ORDER BY last_seq DESC LIMIT 1`).Scan(&previous);if err!=nil&&!errors.Is(err,sql.ErrNoRows){return result,storageError(err)};if err==nil{result.AnchorHash=previous}
 rows,err:=tx.QueryContext(work,`SELECT seq,audit_id,actor_id,action,resource_ref,result_code,occurred_at,hash,previous_hash,metadata,hash_schema_version,producer,actor_kind,source_operation_id,origin_epoch,origin_site_id FROM audit_records WHERE occurred_at<? AND seq<coalesce((SELECT min(seq) FROM audit_records WHERE occurred_at>=?),9223372036854775807) ORDER BY seq LIMIT 10000`,cutoff,cutoff);if err!=nil{return result,storageError(err)};var last int64
 for rows.Next(){var seq int64;var record AuditRecord;if err=rows.Scan(&seq,&record.AuditID,&record.ActorID,&record.Action,&record.ResourceID,&record.ResultCode,&record.OccurredAt,&record.Hash,&record.PreviousHash,&record.Metadata,&record.SchemaVersion,&record.Producer,&record.ActorKind,&record.SourceOperationID,&record.OriginEpoch,&record.SiteID);err!=nil{break};hash,e:=ComputeAuditHash(work,op,ComputeAuditHashInput{PreviousHash:record.PreviousHash,AuditJSON:record});if e!=nil{err=e;break};if record.PreviousHash!=previous||record.Hash!=hash.Hash{err=platform.NewError(platform.CodeIntegrityError,false,"保留期前缀审计链损坏，未删除");break};previous=record.Hash;last=seq;result.Deleted++};if err==nil{err=rows.Err()};_ = rows.Close();if err!=nil{return PurgeAuditHistoryResult{},storageError(err)}
 if result.Deleted!=0{if _,err=tx.ExecContext(work,`INSERT INTO audit_anchors(last_seq,hash,occurred_at) VALUES(?,?,?)`,last,previous,now.UTC().Format(analyticsTimeLayout));err!=nil{return PurgeAuditHistoryResult{},storageError(err)};if _,err=tx.ExecContext(work,`DELETE FROM audit_records WHERE seq<=?`,last);err!=nil{return PurgeAuditHistoryResult{},storageError(err)};result.AnchorHash=previous;metadata,_:=platform.CanonicalJSON(map[string]int64{"count":result.Deleted});record:=AuditRecord{SchemaVersion:2,SiteID:rt.SiteID,Producer:"analytics",ActorKind:op.Actor.Kind,SourceOperationID:op.RootOperationID,OriginEpoch:rt.Epoch,AuditID:"audit.retention."+platform.HashBytes([]byte(op.OperationID)),ActorID:op.Actor.SubjectID,Action:"analytics.retention",ResourceID:"analytics.audit-history",ResultCode:"OK",OccurredAt:now.UTC().Format(analyticsTimeLayout),Metadata:string(metadata)};recordRaw,_:=platform.CanonicalJSON(record);if _,err=insertAuditRecord(work,op,tx,record,false,nil,platform.HashBytes(recordRaw));err!=nil{return PurgeAuditHistoryResult{},err};if _,err=advanceWatermark(work,tx,"audits");err!=nil{return PurgeAuditHistoryResult{},err}}
 if result.Deleted==0{if _,err=advanceWatermark(work,tx,"audit-retention-receipt");err!=nil{return result,err}}
 if err=saveReceipt(work,tx,op,"analytics.PurgeAuditHistory",digest,result);err==nil{err=tx.Commit()};if err!=nil{return PurgeAuditHistoryResult{},storageError(err)};return result,nil
}

// PruneDaySalts在新日或保留循环擦除旧日期独立密钥，不进入业务快照。
func PruneDaySalts(ctx context.Context,rt *Runtime,now time.Time)error{
 if rt.CountingLocation==nil{return nil};today:=now.In(rt.CountingLocation).Format("2006-01-02");rt.mu.Lock();defer rt.mu.Unlock();entries,err:=os.ReadDir(filepath.Join(rt.Root,"control"));if err!=nil{return storageError(err)};changed:=false
 for _,entry:=range entries{if !strings.HasPrefix(entry.Name(),"visitor-")||!strings.HasSuffix(entry.Name(),".key"){continue};day:=strings.TrimSuffix(strings.TrimPrefix(entry.Name(),"visitor-"),".key");if _,e:=time.Parse("2006-01-02",day);e!=nil{return platform.NewError(platform.CodeIntegrityError,false,"匿名盐引用日期不合法")};if day==today{continue};path:=filepath.Join(rt.Root,"control",entry.Name());if err=lifecycle.ValidatePrivatePath(path,"regular-file",false);err!=nil{return err};if err=ctx.Err();err!=nil{return storageError(err)};if err=os.Remove(path);err!=nil{return storageError(err)};if old:=rt.salts[day];old!=nil{clear(old);delete(rt.salts,day)};changed=true};if changed{return syncDirectory(filepath.Join(rt.Root,"control"),rt.Root)};return nil
}
